-- Phase 5 customer and sales engine. SQL-first because tenant isolation and stock history are security-critical.
create table customer_categories (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),code text not null,name text not null,archived_at timestamptz,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,code));
create table price_lists (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),code text not null,name text not null,currency text not null check(length(currency)=3),tax_inclusive boolean not null default false,effective_from date not null,effective_to date,archived_at timestamptz,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,code));
create table customers (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),category_id uuid,default_price_list_id uuid,salesperson_id uuid references users(id),code text not null,legal_name text not null,display_name text not null,contact_person text,mobile_number text,email text,tax_registration_number text,tax_identity_number text,payment_terms_days integer not null default 0 check(payment_terms_days>=0),credit_limit numeric(20,4) not null default 0 check(credit_limit>=0),default_currency text not null check(length(default_currency)=3),active boolean not null default false,notes text,attachment_references jsonb not null default '[]',archived_at timestamptz,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,code),foreign key(company_id,category_id) references customer_categories(company_id,id),foreign key(company_id,default_price_list_id) references price_lists(company_id,id));
create table customer_contacts (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_id uuid not null,name text not null,role text,phone text,email text,is_primary boolean not null default false,archived_at timestamptz,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,customer_id) references customers(company_id,id));
create table customer_addresses (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_id uuid not null,address_type text not null check(address_type in('BILLING','SHIPPING','OTHER')),line1 text not null,line2 text,city text not null,region text,postal_code text,country_code text not null,is_primary boolean not null default false,archived_at timestamptz,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,customer_id) references customers(company_id,id));
create table price_list_items (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),price_list_id uuid not null,variant_id uuid not null,packaging_level_id uuid,unit_price numeric(20,4) not null check(unit_price>=0),minimum_selling_price numeric(20,4) not null default 0 check(minimum_selling_price>=0),effective_from date not null,effective_to date,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,price_list_id) references price_lists(company_id,id),foreign key(company_id,variant_id) references product_variants(company_id,id),foreign key(company_id,packaging_level_id) references product_packaging_levels(company_id,id));
create table customer_price_assignments (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_id uuid,customer_category_id uuid,price_list_id uuid not null,effective_from date not null,effective_to date,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,customer_id) references customers(company_id,id),foreign key(company_id,customer_category_id) references customer_categories(company_id,id),foreign key(company_id,price_list_id) references price_lists(company_id,id));

create table sales_quotations (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_id uuid not null,reference_number text not null,status text not null default 'DRAFT',business_date date not null,valid_until date not null,currency text not null,subtotal numeric(20,4) not null,discount_total numeric(20,4) not null default 0,tax_total numeric(20,4) not null default 0,grand_total numeric(20,4) not null,sent_at timestamptz,accepted_at timestamptz,converted_order_id uuid,notes text,version integer not null default 1,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,reference_number),foreign key(company_id,customer_id) references customers(company_id,id));
create table sales_quotation_lines (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),quotation_id uuid not null,variant_id uuid not null,packaging_level_id uuid,warehouse_id uuid not null,package_quantity numeric(24,8) not null check(package_quantity>0),conversion_snapshot numeric(24,8) not null check(conversion_snapshot>0),base_quantity numeric(24,8) not null check(base_quantity>0),package_unit_price numeric(20,4) not null,discount_amount numeric(20,4) not null default 0,tax_amount numeric(20,4) not null default 0,line_total numeric(20,4) not null,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,quotation_id) references sales_quotations(company_id,id),foreign key(company_id,variant_id) references product_variants(company_id,id),foreign key(company_id,packaging_level_id) references product_packaging_levels(company_id,id),foreign key(company_id,warehouse_id) references warehouses(company_id,id));
create table sales_orders (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_id uuid not null,quotation_id uuid,reference_number text not null,status text not null default 'DRAFT',business_date date not null,expected_delivery_date date,currency text not null,subtotal numeric(20,4) not null,discount_total numeric(20,4) not null default 0,tax_total numeric(20,4) not null default 0,grand_total numeric(20,4) not null,submitted_at timestamptz,approved_at timestamptz,approved_by uuid references users(id),credit_override_reason text,notes text,version integer not null default 1,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,reference_number),foreign key(company_id,customer_id) references customers(company_id,id),foreign key(company_id,quotation_id) references sales_quotations(company_id,id));
create table sales_order_lines (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),sales_order_id uuid not null,variant_id uuid not null,packaging_level_id uuid,warehouse_id uuid not null,package_quantity numeric(24,8) not null,conversion_snapshot numeric(24,8) not null,base_quantity numeric(24,8) not null,reserved_base_quantity numeric(24,8) not null default 0,dispatched_base_quantity numeric(24,8) not null default 0,returned_base_quantity numeric(24,8) not null default 0,invoiced_base_quantity numeric(24,8) not null default 0,package_unit_price numeric(20,4) not null,discount_amount numeric(20,4) not null default 0,tax_amount numeric(20,4) not null default 0,line_total numeric(20,4) not null,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,sales_order_id) references sales_orders(company_id,id),foreign key(company_id,variant_id) references product_variants(company_id,id),foreign key(company_id,packaging_level_id) references product_packaging_levels(company_id,id),foreign key(company_id,warehouse_id) references warehouses(company_id,id));
create table sales_order_approvals (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),sales_order_id uuid not null,decision text not null,reason text,decided_at timestamptz not null default now(),created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,sales_order_id) references sales_orders(company_id,id));
create table stock_reservations (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),sales_order_id uuid not null,reference_number text not null,status text not null default 'ACTIVE',business_date date not null,expires_at timestamptz,released_at timestamptz,notes text,version integer not null default 1,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,reference_number),foreign key(company_id,sales_order_id) references sales_orders(company_id,id));
create table stock_reservation_lines (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),reservation_id uuid not null,sales_order_line_id uuid not null,variant_id uuid not null,warehouse_id uuid not null,reserved_base_quantity numeric(24,8) not null,fulfilled_base_quantity numeric(24,8) not null default 0,released_base_quantity numeric(24,8) not null default 0,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,reservation_id) references stock_reservations(company_id,id),foreign key(company_id,sales_order_line_id) references sales_order_lines(company_id,id),foreign key(company_id,variant_id) references product_variants(company_id,id),foreign key(company_id,warehouse_id) references warehouses(company_id,id));

create table delivery_challans (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),sales_order_id uuid not null,customer_id uuid not null,reference_number text not null,status text not null default 'DRAFT',business_date date not null,inventory_transaction_id uuid,posted_at timestamptz,posted_by uuid references users(id),notes text,version integer not null default 1,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,reference_number),foreign key(company_id,sales_order_id) references sales_orders(company_id,id),foreign key(company_id,customer_id) references customers(company_id,id),foreign key(company_id,inventory_transaction_id) references inventory_transactions(company_id,id));
create table delivery_challan_lines (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),delivery_challan_id uuid not null,sales_order_line_id uuid not null,variant_id uuid not null,packaging_level_id uuid,warehouse_id uuid not null,location_id uuid,package_quantity numeric(24,8) not null,conversion_snapshot numeric(24,8) not null,base_quantity numeric(24,8) not null,inventory_transaction_line_id uuid,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,delivery_challan_id) references delivery_challans(company_id,id),foreign key(company_id,sales_order_line_id) references sales_order_lines(company_id,id),foreign key(company_id,variant_id) references product_variants(company_id,id),foreign key(company_id,warehouse_id) references warehouses(company_id,id),foreign key(company_id,location_id) references warehouse_locations(company_id,id));
create table delivery_challan_batches (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),delivery_challan_line_id uuid not null,batch_number text not null,expiry_date date,base_quantity numeric(24,8) not null,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,delivery_challan_line_id) references delivery_challan_lines(company_id,id));
create table delivery_challan_serial_numbers (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),delivery_challan_line_id uuid not null,serial_number text not null,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,serial_number),foreign key(company_id,delivery_challan_line_id) references delivery_challan_lines(company_id,id));
create table sales_invoices (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_id uuid not null,sales_order_id uuid,delivery_challan_id uuid,reference_number text not null,status text not null default 'DRAFT',business_date date not null,currency text not null,invoice_total numeric(20,4) not null,outstanding_amount numeric(20,4) not null,immediate_delivery boolean not null default false,linked_dispatch_id uuid,issued_at timestamptz,notes text,version integer not null default 1,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,reference_number),foreign key(company_id,customer_id) references customers(company_id,id),foreign key(company_id,sales_order_id) references sales_orders(company_id,id),foreign key(company_id,delivery_challan_id) references delivery_challans(company_id,id));
create table sales_invoice_lines (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),sales_invoice_id uuid not null,delivery_challan_line_id uuid,sales_order_line_id uuid,variant_id uuid not null,packaging_level_id uuid,package_quantity numeric(24,8) not null,conversion_snapshot numeric(24,8) not null,base_quantity numeric(24,8) not null,package_unit_price numeric(20,4) not null,discount_amount numeric(20,4) not null default 0,tax_amount numeric(20,4) not null default 0,line_total numeric(20,4) not null,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,sales_invoice_id) references sales_invoices(company_id,id),foreign key(company_id,delivery_challan_line_id) references delivery_challan_lines(company_id,id),foreign key(company_id,sales_order_line_id) references sales_order_lines(company_id,id),foreign key(company_id,variant_id) references product_variants(company_id,id));
create table sales_returns (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_id uuid not null,sales_invoice_id uuid,delivery_challan_id uuid not null,reference_number text not null,status text not null default 'DRAFT',business_date date not null,reason text not null,condition text not null,inventory_transaction_id uuid,posted_at timestamptz,posted_by uuid references users(id),notes text,version integer not null default 1,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,reference_number),foreign key(company_id,customer_id) references customers(company_id,id),foreign key(company_id,sales_invoice_id) references sales_invoices(company_id,id),foreign key(company_id,delivery_challan_id) references delivery_challans(company_id,id),foreign key(company_id,inventory_transaction_id) references inventory_transactions(company_id,id));
create table sales_return_lines (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),sales_return_id uuid not null,delivery_challan_line_id uuid not null,variant_id uuid not null,warehouse_id uuid not null,location_id uuid,package_quantity numeric(24,8) not null,conversion_snapshot numeric(24,8) not null,base_quantity numeric(24,8) not null,inventory_transaction_line_id uuid,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,sales_return_id) references sales_returns(company_id,id),foreign key(company_id,delivery_challan_line_id) references delivery_challan_lines(company_id,id));
create table sales_return_batches (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),sales_return_line_id uuid not null,batch_number text not null,expiry_date date,base_quantity numeric(24,8) not null,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,sales_return_line_id) references sales_return_lines(company_id,id));
create table sales_return_serial_numbers (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),sales_return_line_id uuid not null,serial_number text not null,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,sales_return_line_id) references sales_return_lines(company_id,id));
create table credit_notes (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_id uuid not null,sales_invoice_id uuid,sales_return_id uuid,reference_number text not null,status text not null default 'DRAFT',business_date date not null,currency text not null,total_amount numeric(20,4) not null,reason text not null,approved_at timestamptz,approved_by uuid references users(id),notes text,version integer not null default 1,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,reference_number),foreign key(company_id,customer_id) references customers(company_id,id),foreign key(company_id,sales_invoice_id) references sales_invoices(company_id,id),foreign key(company_id,sales_return_id) references sales_returns(company_id,id));
create table credit_note_lines (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),credit_note_id uuid not null,sales_invoice_line_id uuid,sales_return_line_id uuid,amount numeric(20,4) not null,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,credit_note_id) references credit_notes(company_id,id));
create table customer_payments (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_id uuid not null,reference_number text not null,status text not null default 'POSTED',business_date date not null,payment_method text not null,currency text not null,amount numeric(20,4) not null check(amount>0),payment_reference text not null,notes text,version integer not null default 1,created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),unique(company_id,reference_number),foreign key(company_id,customer_id) references customers(company_id,id));
create table customer_payment_allocations (id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_payment_id uuid not null,sales_invoice_id uuid not null,allocated_amount numeric(20,4) not null check(allocated_amount>0),created_at timestamptz not null default now(),created_by uuid references users(id),updated_at timestamptz not null default now(),updated_by uuid references users(id),unique(company_id,id),foreign key(company_id,customer_payment_id) references customer_payments(company_id,id),foreign key(company_id,sales_invoice_id) references sales_invoices(company_id,id));

create index customers_company_name_idx on customers(company_id,display_name) where archived_at is null;
create index sales_quotations_company_customer_status_idx on sales_quotations(company_id,customer_id,status,business_date);
create index sales_orders_company_customer_status_idx on sales_orders(company_id,customer_id,status,business_date);
create index stock_reservation_lines_company_variant_idx on stock_reservation_lines(company_id,variant_id,warehouse_id);
create index delivery_challans_company_order_idx on delivery_challans(company_id,sales_order_id,business_date);
create index sales_invoices_company_customer_status_idx on sales_invoices(company_id,customer_id,status,business_date);
create index sales_returns_company_delivery_idx on sales_returns(company_id,delivery_challan_id);
create index customer_payments_company_customer_idx on customer_payments(company_id,customer_id,business_date);
create index customer_payment_allocations_company_invoice_idx on customer_payment_allocations(company_id,sales_invoice_id);

create or replace function reject_sales_history_mutation() returns trigger language plpgsql as $$ begin raise exception 'posted sales history is append-only'; end $$;
create trigger sales_order_approvals_immutable before update or delete on sales_order_approvals for each row execute function reject_sales_history_mutation();
create trigger customer_payment_allocations_immutable before update or delete on customer_payment_allocations for each row execute function reject_sales_history_mutation();
create trigger credit_note_lines_immutable before update or delete on credit_note_lines for each row execute function reject_sales_history_mutation();
create trigger delivery_tracking_immutable before update or delete on delivery_challan_serial_numbers for each row execute function reject_sales_history_mutation();

DO $sales_rls$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['customers','customer_contacts','customer_addresses','customer_categories','customer_price_assignments','price_lists','price_list_items','sales_quotations','sales_quotation_lines','sales_orders','sales_order_lines','sales_order_approvals','stock_reservations','stock_reservation_lines','delivery_challans','delivery_challan_lines','delivery_challan_batches','delivery_challan_serial_numbers','sales_invoices','sales_invoice_lines','sales_returns','sales_return_lines','sales_return_batches','sales_return_serial_numbers','credit_notes','credit_note_lines','customer_payments','customer_payment_allocations'] LOOP EXECUTE format('alter table %I enable row level security',table_name); EXECUTE format('alter table %I force row level security',table_name); EXECUTE format('create policy %I on %I using (company_id = current_setting(''app.current_company_id'',true)::uuid) with check (company_id = current_setting(''app.current_company_id'',true)::uuid)',table_name||'_tenant_policy',table_name); END LOOP; END $sales_rls$;
